  const r = crypto.timingSafeEqual(Buffer.from("abc"), Buffer.from("ab"));
  console.log("length mismatch returned:", r);
} catch (e) {
  console.log("length mismatch throws:", e.constructor.name, e.message);
}
// Case B: two empty buffers
try {
  const r = crypto.timingSafeEqual(Buffer.from(""), Buffer.from(""));
  console.log("empty buffers equal returned:", r);
} catch (e) {
  console.log("empty buffers throws:", e.constructor.name);
}
// Case C: Buffer.from(undefined)
try {
  const b = Buffer.from(undefined);
  console.log("Buffer.from(undefined) =", b, "len", b.length);
} catch (e) {
  console.log("Buffer.from(undefined) throws:", e.constructor.name, e.message);
}
// Case D: oauthState unset -> Buffer.from(undefined) throws, so verifyState crashes
try {
  const session = {}; // no oauthState
  crypto.timingSafeEqual(Buffer.from(session.oauthState), Buffer.from("anything"));
  console.log("unset oauthState did not throw");
} catch (e) {
  console.log("unset oauthState throws:", e.constructor.name);
}
'
"}

